CREATE OR REPLACE FUNCTION public.close_payroll_period(_period_id uuid, _reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$<<finance_payroll_lifecycle_guard>>
BEGIN
perform finance_private.lock_payroll_lifecycle((select tenant_id from public.payroll_periods where id=_period_id),_period_id,null,'close');
<<finance_entry_guard>>
BEGIN
 PERFORM finance_private.require_access((select financial_scope.tenant_id from public.payroll_periods financial_scope where financial_scope.id=_period_id));
 <<legacy_financial_body>>

DECLARE
  _tenant uuid;
  _open_balance numeric(14,2);
  _user uuid := auth.uid();
BEGIN
  SELECT tenant_id INTO _tenant FROM public.payroll_periods WHERE id = _period_id;
  IF _tenant IS NULL THEN RAISE EXCEPTION 'período não encontrado'; END IF;
  IF NOT public.is_tenant_admin(_tenant) THEN RAISE EXCEPTION 'somente admin/owner pode fechar folha'; END IF;


 DECLARE projection jsonb;
 BEGIN
  PERFORM 1 FROM public.payroll_periods WHERE id=_period_id AND tenant_id=_tenant AND status='approved' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'finance_payroll_close_requires_approved' USING ERRCODE='22023';END IF;
  projection:=finance_private.payroll_payment_projection(_tenant,_period_id);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(projection->'rows') r
    WHERE jsonb_array_length(r->'payment_summary'->'issues')>0) THEN
   RAISE EXCEPTION 'finance_payroll_payment_review_required' USING ERRCODE='22023';
  END IF;
  SELECT coalesce(sum((r->'payment_summary'->>'remaining_amount')::numeric),0)
    INTO _open_balance FROM jsonb_array_elements(projection->'rows') r;
 END;

  IF _reason IS NULL OR length(trim(_reason)) = 0 THEN
    RAISE EXCEPTION 'saldo em aberto (%), motivo obrigatório', _open_balance;
  END IF;

  UPDATE public.payroll_periods
     SET status = 'closed', closed_by = _user, closed_at = now(),
         notes = COALESCE(notes,'') || CASE WHEN _reason IS NOT NULL THEN E'\n[Fechamento] '||_reason ELSE '' END,
         updated_at = now()
   WHERE id = _period_id;
END;

END;

END finance_payroll_lifecycle_guard;$function$
;

CREATE OR REPLACE FUNCTION finance_private.effective_cost_amount(t uuid, expense uuid, strict boolean DEFAULT false)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$declare v jsonb;begin
 v:=finance_private.expense_cost_effective(t,expense);
