CREATE OR REPLACE FUNCTION public.reassign_finance_statement_account_v1(_tenant_id uuid, _import_id uuid, _account_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  statement_import public.finance_statement_imports%rowtype;
  old_account uuid;
  entry_ids uuid[];
  actor_name text;
begin
  perform finance_private.require_access(_tenant_id);
  if length(btrim(coalesce(_reason,'')))<10 then
    raise exception 'reason_required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':finance',0));
  select * into statement_import
  from public.finance_statement_imports
  where tenant_id=_tenant_id and id=_import_id
  for update;
  if not found then raise exception 'statement_not_found';end if;
  old_account:=statement_import.bank_account_id;
  if not exists(
    select 1 from public.bank_accounts
    where tenant_id=_tenant_id and id=_account_id and active and account_type<>'cash'
  ) then raise exception 'invalid_target_account';end if;
  select array_agg(id) into entry_ids
  from public.finance_bank_entries
  where tenant_id=_tenant_id and first_import_id=_import_id;
  if exists(
    select 1 from public.finance_reconciliation_groups
    where tenant_id=_tenant_id and bank_entry_ids && coalesce(entry_ids,'{}'::uuid[])
  ) then raise exception 'statement_already_reconciled';end if;
  if exists(
    select 1
    from public.finance_statement_identity_reviews review
    join public.finance_statement_rows statement_row
      on statement_row.tenant_id=review.tenant_id and statement_row.id=review.row_id
    where statement_row.import_id=_import_id
  ) then raise exception 'statement_identity_review_exists';end if;
  update public.finance_statement_imports
    set bank_account_id=_account_id
  where tenant_id=_tenant_id and id=_import_id;
  update public.finance_bank_entries
    set bank_account_id=_account_id
  where tenant_id=_tenant_id and first_import_id=_import_id;
  select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,auth.uid()::text)
    into actor_name from auth.users where id=auth.uid();
  insert into public.finance_events(
    tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,before_data,after_data
  ) values (
    _tenant_id,'statement_import',_import_id,'statement_account_reassigned',auth.uid(),
    coalesce(actor_name,auth.uid()::text),btrim(_reason),
    jsonb_build_object('bank_account_id',old_account),
    jsonb_build_object('bank_account_id',_account_id,'manual_intervention',true)
  );
  return jsonb_build_object('confirmed',true,'import_id',_import_id,'bank_account_id',_account_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION finance_private.payable_movement_options(_tenant uuid, _payable uuid, _search text DEFAULT ''::text, _page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.payables%rowtype;result jsonb;paid numeric;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _page is null or _page not between 1 and 1000000 or length(coalesce(_search,''))>200 then raise exception 'finance_invalid_options' using errcode='22023';end if;
 select * into p from public.payables where id=_payable and tenant_id=_tenant;
 if not found then raise exception 'finance_payable_not_found' using errcode='22023';end if;
 select coalesce(sum(amount),0) into paid from finance_private.active_payable_payments where tenant_id=_tenant and payable_id=_payable;
 with candidates as materialized (
  select m.id,m.beneficiary_name,m.description,m.occurred_on,m.bank_reference,m.bank_account_id,b.name account_name,
   m.amount_cents::text amount_cents,(m.amount_cents-finance_private.movement_used_cents(_tenant,m.id))::text remaining_cents
  from finance_private.active_movements m join public.bank_accounts b on b.id=m.bank_account_id and b.tenant_id=_tenant
  where m.tenant_id=_tenant and m.direction='out' and m.nature<>'transfer'
   and (p.driver_id is null or m.driver_id=p.driver_id)
   and m.amount_cents>finance_private.movement_used_cents(_tenant,m.id)
   and position(lower(coalesce(_search,'')) in lower(m.beneficiary_name||' '||m.description||' '||coalesce(m.bank_reference,'')||' '||b.name||' '||m.id::text))>0
 ), paged as(select * from candidates order by occurred_on desc,id limit 30 offset (_page-1)*30)
 select jsonb_build_object('version',1,'tenant_id',_tenant,'payable_id',_payable,'page',_page,'total',(select count(*) from candidates),
  'payable_status',p.status,'payable_name',p.supplier_name,'remaining_cents',(greatest(p.amount-paid,0)*100)::numeric(30,0)::text,
  'can_apply',p.status in('approved','partial') and paid>=0 and paid=trunc(paid,2) and p.amount>paid,
  'rows',coalesce((select jsonb_agg(to_jsonb(row) order by row.occurred_on desc,row.id) from paged row),'[]')) into result;
 return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION finance_private.payable_payment_history(_tenant uuid, _payable uuid, _page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if _page is null or _page not between 1 and 1000000 then raise exception 'finance_invalid_page' using errcode='22023';end if;
 if not exists(select 1 from public.payables where tenant_id=_tenant and id=_payable) then raise exception 'finance_payable_not_found' using errcode='22023';end if;
 with payments as materialized(select p.*,b.name account_name,l.id link_id,l.movement_id,l.origin link_origin,
  case when r.id is null then null else jsonb_build_object('id',r.id,'actor_id',r.created_by,'actor_name',r.actor_name,'reason',r.reason,'created_at',r.created_at) end reversal
  from public.payables_payments p left join public.bank_accounts b on b.id=p.bank_account_id and b.tenant_id=_tenant
  left join lateral(select l.* from public.finance_payable_movement_links l where l.payment_id=p.id and l.tenant_id=_tenant
 order by exists(select 1 from public.finance_payable_link_reversals rv where rv.tenant_id=l.tenant_id and rv.link_id=l.id),l.created_at desc,l.id desc limit 1) l on true
  left join public.finance_payable_link_reversals r on r.link_id=l.id and r.tenant_id=_tenant
  where p.tenant_id=_tenant and p.payable_id=_payable
 ), paged as(select * from payments order by paid_at desc,id desc limit 30 offset (_page-1)*30)
 select jsonb_build_object('version',1,'tenant_id',_tenant,'payable_id',_payable,'page',_page,'total',(select count(*) from payments),
  'rows',coalesce((select jsonb_agg(to_jsonb(p) order by p.paid_at desc,p.id desc) from paged p),'[]')) into result;
 return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION finance_private.run_fiscal_queue(_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare candidate record;job public.finance_fiscal_projection_jobs%rowtype;outcome jsonb;
 handled integer:=0;deferred integer:=0;failed integer:=0;error_code text;started timestamptz:=clock_timestamp();
begin
 if auth.uid() is not null then raise exception 'finance_system_worker_only' using errcode='42501';end if;
 if _limit is null or _limit<1 or _limit>100 then raise exception 'finance_invalid_batch_limit' using errcode='22023';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('finance:fiscal-queue-worker',0)) then
  return jsonb_build_object('handled',0,'deferred',0,'failed',0,'busy',true);end if;
 for candidate in select j.observation_id,j.tenant_id from public.finance_fiscal_projection_jobs j
  join public.finance_fiscal_observations o on o.id=j.observation_id and o.tenant_id=j.tenant_id
  where j.status='pending' and j.available_at<=started
  order by j.available_at,o.observed_order limit _limit
 loop
  exit when clock_timestamp()-started>interval '20 seconds';
  -- Same lock order as manual projection and receipt commands; skip busy tenants.
  if not pg_try_advisory_xact_lock(hashtextextended('fiscal:'||candidate.tenant_id::text,0))
   or not pg_try_advisory_xact_lock(hashtextextended(candidate.tenant_id::text||':finance',0)) then
   deferred:=deferred+1;continue;end if;
  select * into job from public.finance_fiscal_projection_jobs
   where observation_id=candidate.observation_id and tenant_id=candidate.tenant_id and status='pending'
    and available_at<=started for update skip locked;
  if not found then deferred:=deferred+1;continue;end if;
  begin
   outcome:=finance_private.process_fiscal_observation(job.tenant_id,job.observation_id);
   handled:=handled+1;
   update public.finance_fiscal_projection_jobs set last_error_code=null where observation_id=job.observation_id;
  exception when others then
   get stacked diagnostics error_code=returned_sqlstate;
   failed:=failed+1;
   update public.finance_fiscal_projection_jobs set automatic_failures=automatic_failures+1,attempts=attempts+1,
    status=case when automatic_failures>=4 then 'review' else 'pending' end,
    issue=case when automatic_failures>=4 then 'automatic_projection_failed' else 'automatic_projection_retry' end,
    last_error_code=error_code,available_at=clock_timestamp()+make_interval(secs=>30*power(2,least(automatic_failures,6))::integer),updated_at=clock_timestamp()
   where observation_id=job.observation_id;
   insert into public.finance_fiscal_projection_events(tenant_id,observation_id,actor_id,action,after_data)
   values(job.tenant_id,job.observation_id,null,'automatic_projection_failure',
    jsonb_build_object('error_code',error_code,'attempt',job.automatic_failures+1,'requires_review',job.automatic_failures>=4));
  end;
 end loop;
 return jsonb_build_object('handled',handled,'deferred',deferred,'failed',failed,'busy',false);
end;$function$
;

CREATE OR REPLACE FUNCTION finance_private.expense_cost_coverage_before_returns(t uuid, expense uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.finance_expense_items%rowtype;p public.payables%rowtype;cost jsonb;reg jsonb;d jsonb;issue text;raw_alloc numeric:=0;raw_paid numeric:=0;alloc_applied numeric:=0;pay_applied numeric:=0;gross numeric:=0;applied numeric:=0;residual numeric:=0;custody numeric:=0;recovery numeric:=0;g numeric;a numeric;r numeric;nominal numeric:=0;complement numeric;seen text[]:='{}';
begin
 select * into e from public.finance_expense_items where tenant_id=t and id=expense;
 if not found then issue:='finance_cost_source_missing';else
 cost:=finance_private.expense_cost_effective(t,expense);reg:=nullif(cost->'regularization','null'::jsonb);
 select coalesce(sum(amount_cents),0) into raw_alloc from public.finance_expense_allocations where tenant_id=t and expense_id=expense;
 if e.payable_id is not null then
  select * into p from public.payables where tenant_id=t and id=e.payable_id;
  if not found or p.source_table is distinct from 'finance_expense_items' or p.source_id is distinct from e.id then issue:='finance_cost_obligation_missing';end if;
  nominal:=p.amount*100;select coalesce(sum(amount*100),0) into raw_paid from finance_private.active_payable_payments where tenant_id=t and payable_id=e.payable_id;
 end if;
 if cost->'verified' is distinct from 'true'::jsonb or coalesce(cost->>'effective_amount_cents','') !~ '^[0-9]{1,14}$' then issue:='finance_cost_version_unverified';end if;
 if raw_alloc<0 or raw_alloc<>trunc(raw_alloc) or raw_paid<0 or raw_paid<>trunc(raw_paid) or nominal<0 or nominal<>trunc(nominal) then issue:='finance_cost_source_amount_invalid';end if;
 raw_alloc:=trunc(raw_alloc);raw_paid:=trunc(raw_paid);nominal:=trunc(nominal);if raw_alloc::text !~ '^[0-9]+$' or raw_paid::text !~ '^[0-9]+$' or nominal::text !~ '^[0-9]+$' then issue:='finance_cost_source_amount_invalid';end if;
 if reg is null then
  gross:=raw_alloc+raw_paid;alloc_applied:=raw_alloc;pay_applied:=raw_paid;applied:=gross;
  if issue is null then complement:=(cost->>'effective_amount_cents')::numeric-raw_alloc;if complement<0 or applied>(cost->>'effective_amount_cents')::numeric then issue:='finance_cost_coverage_unverified';end if;end if;
 else
  if jsonb_typeof(reg->'dispositions') is distinct from 'array' or jsonb_array_length(reg->'dispositions')=0 then issue:='finance_cost_disposition_unverified';
  else
   for d in select value from jsonb_array_elements(reg->'dispositions') loop
    if coalesce(d->>'gross_reserved_cents','') !~ '^[0-9]{1,14}$' or coalesce(d->>'applied_cents','') !~ '^[0-9]{1,14}$' or coalesce(d->>'residual_cents','') !~ '^[0-9]{1,14}$'
    or d->>'status' is distinct from 'pending' or ((d->>'source_kind')||':'||(d->>'source_id'))=any(seen) then issue:='finance_cost_disposition_unverified';exit;end if;
    seen:=array_append(seen,(d->>'source_kind')||':'||(d->>'source_id'));g:=(d->>'gross_reserved_cents')::numeric;a:=(d->>'applied_cents')::numeric;r:=(d->>'residual_cents')::numeric;
    if g<=0 or g<>a+r then issue:='finance_cost_disposition_unverified';exit;end if;
    if d->>'source_kind'='expense_allocation' then
     if d->>'disposition_type' is distinct from 'driver_custody' or not exists(select 1 from public.finance_expense_allocations x where x.tenant_id=t and x.expense_id=expense and x.id::text=d->>'source_id' and x.movement_id::text=d->>'movement_id' and x.amount_cents=g) then issue:='finance_cost_disposition_source_mismatch';exit;end if;
     alloc_applied:=alloc_applied+a;custody:=custody+r;
    elsif d->>'source_kind'='payable_link' then
     if d->>'disposition_type' is distinct from 'payment_recovery' or not exists(select 1 from public.finance_payable_movement_links x join finance_private.active_payable_payments pp on pp.tenant_id=x.tenant_id and pp.id=x.payment_id where x.tenant_id=t and x.payable_id=e.payable_id and x.id::text=d->>'source_id' and x.payment_id::text=d->>'payment_id' and x.movement_id::text=d->>'movement_id' and x.amount_cents=g and pp.amount*100=g and not exists(select 1 from public.finance_payable_link_reversals rv where rv.tenant_id=t and rv.link_id=x.id)) then issue:='finance_cost_disposition_source_mismatch';exit;end if;
     pay_applied:=pay_applied+a;recovery:=recovery+r;
    else issue:='finance_cost_disposition_source_mismatch';exit;end if;
    gross:=gross+g;applied:=applied+a;residual:=residual+r;
   end loop;
  end if;
  if issue is null and (gross<>raw_alloc+raw_paid or raw_alloc>0 and raw_paid>0 or applied<>(cost->>'effective_amount_cents')::numeric or gross::text is distinct from reg->>'gross_reserved_cents' or applied::text is distinct from reg->>'applied_cents' or residual::text is distinct from reg->>'residual_cents') then issue:='finance_cost_disposition_totals_mismatch';end if;
  complement:=case when e.payable_id is null then 0 else nominal end;
 end if;
 end if;
 return jsonb_build_object('verified',issue is null,'issue',issue,'regularization_id',reg->'id','allocation_reserved_cents',case when issue is null then raw_alloc::text end,'payment_reserved_cents',case when issue is null then raw_paid::text end,'gross_reserved_cents',case when issue is null then gross::text end,'allocation_applied_cents',case when issue is null then alloc_applied::text end,'payment_applied_cents',case when issue is null then pay_applied::text end,'applied_cents',case when issue is null then applied::text end,'residual_cents',case when issue is null then residual::text end,'driver_custody_cents',case when issue is null then custody::text end,'payment_recovery_cents',case when issue is null then recovery::text end,'complement_cents',case when issue is null then complement::text end,'obligation_nominal_cents',case when issue is null then nominal::text end,'uncovered_cents',case when issue is null then (case when reg is not null then 0 else (cost->>'effective_amount_cents')::numeric-applied end)::text end,'dispositions',case when issue is null then coalesce(reg->'dispositions','[]'::jsonb) else '[]'::jsonb end);
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.lock_payroll_lifecycle(_tenant uuid, _period uuid, _entry uuid, _mode text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare p public.payroll_periods%rowtype;e public.payroll_entries%rowtype;begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(_tenant::text||':finance',0));
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 perform id from public.payroll_periods where tenant_id=_tenant and (_period is null or id=_period) order by id for update;
 -- Generation already owns finance and the period set before its INSERTs.
 -- Recomputing one entry must not repeatedly lock every historical payroll.
 perform id from public.payroll_entries where tenant_id=_tenant and payroll_period_id=_period and (_entry is null or id=_entry) order by id for update;
 if _mode='generate' then return;end if;
 select * into p from public.payroll_periods where id=_period and tenant_id=_tenant;
 if not found then raise exception 'finance_payroll_period_not_found' using errcode='22023';end if;
 if (_mode='close' and p.status<>'approved') or (_mode<>'close' and p.status not in('draft','calculated')) then
  raise exception 'finance_payroll_period_protected' using errcode='55000';end if;
 if _entry is not null then
  select * into e from public.payroll_entries where id=_entry and tenant_id=_tenant and payroll_period_id=_period;
  if not found or e.status not in('draft','calculated') then raise exception 'finance_payroll_entry_protected' using errcode='55000';end if;
 elsif _mode='approve' and exists(select 1 from public.payroll_entries where tenant_id=_tenant and payroll_period_id=_period and status not in('draft','calculated','cancelled')) then
  raise exception 'finance_payroll_entry_protected' using errcode='55000';
 end if;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.unloading_effective_origin(t uuid, charge uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb;original jsonb;current_state jsonb;rev text;history jsonb:='[]';effects jsonb;item finance_private.unloading_origin_amendments%rowtype;
 previous uuid;position integer:=0;valid boolean;issue text;last_day date;result jsonb;
begin
 base:=finance_private.unloading_origin_base(t,charge);
 original:=jsonb_build_object('supplier_id',base#>'{original,supplier_id}','supplier_name',base#>'{original,supplier_name}','amount_cents',base#>'{original,amount_cents}','status','active');
 current_state:=original;valid:=base->>'origin_verified'='true';
 if valid is distinct from true then issue:='unloading_origin_unverified';end if;
 rev:=md5(jsonb_build_object('charge',base#>'{_evidence,charge}','commands',base#>'{_evidence,commands}','events',base#>'{_evidence,events}')::text);
 last_day:=(base#>>'{_evidence,charge,occurred_on}')::date;
 for item in select * from finance_private.unloading_origin_amendments where tenant_id=t and charge_id=charge order by ordinal loop
  position:=position+1;
  if item.ordinal<>position or item.previous_id is distinct from previous or item.revision_before<>rev or item.before_state<>current_state
   or item.receivable_id::text is distinct from base->>'receivable_id' or current_state->>'status'<>'active' or item.effective_on<last_day
   or not exists(select 1 from public.finance_commands c where c.tenant_id=t and c.request_id=item.request_id and c.actor_id=item.actor_id and c.action='correct_unloading_origin' and c.result->>'amendment_id'=item.id::text and c.payload->>'charge_id'=charge::text)
   or not exists(select 1 from public.finance_events e where e.tenant_id=t and e.entity_type='unloading' and e.entity_id=charge and e.actor_id=item.actor_id and e.action='unloading_origin_corrected' and e.after_data->>'amendment_id'=item.id::text and e.before_data=item.before_state and e.after_data->'effective'=item.after_state)
   or item.after_state->>'status' is distinct from (case when item.operation='cancel_origin' then 'cancelled' else 'active' end)
   or jsonb_typeof(item.after_state) is distinct from 'object' or not(item.after_state ?& array['supplier_id','supplier_name','amount_cents','status'])
   or exists(select 1 from jsonb_object_keys(item.after_state) k where k<>all(array['supplier_id','supplier_name','amount_cents','status']))
   or coalesce(item.after_state->>'supplier_id','')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
   or (item.operation='amend_origin' and (coalesce(item.after_state->>'amount_cents','')!~'^[1-9][0-9]{0,13}$' or item.after_state=item.before_state))
   or (item.operation='cancel_origin' and (item.after_state->>'amount_cents' is distinct from '0' or item.after_state->'supplier_id' is distinct from item.before_state->'supplier_id'))
  then valid:=false;issue:='unloading_amendment_chain_invalid';end if;
  effects:=jsonb_build_array(jsonb_build_object('leg','release','supplier_id',item.before_state->'supplier_id','supplier_name',item.before_state->'supplier_name','amount_cents','-'||(item.before_state->>'amount_cents')));
  if item.operation='amend_origin' then effects:=effects||jsonb_build_array(jsonb_build_object('leg','recognize','supplier_id',item.after_state->'supplier_id','supplier_name',item.after_state->'supplier_name','amount_cents',item.after_state->>'amount_cents'));end if;
  rev:=md5(jsonb_build_object('previous',rev,'event',to_jsonb(item))::text);
  history:=history||jsonb_build_array(jsonb_build_object('revision_after',rev,'id',item.id,'previous_id',item.previous_id,'ordinal',item.ordinal,'operation',item.operation,'effective_on',item.effective_on,'created_at',item.created_at,'actor_id',item.actor_id,'actor_name',item.actor_name,'reason',item.reason,'before',item.before_state,'after',item.after_state,'economic_effects',effects));
  current_state:=item.after_state;previous:=item.id;last_day:=item.effective_on;
 end loop;
 result:=jsonb_build_object('version',1,'tenant_id',t,'charge_id',charge,'receivable_id',base->'receivable_id','verified',coalesce(valid,false),'issue',issue,'original',original,'effective',case when valid then current_state end,'revision',rev,'history',history,'last_effective_on',last_day);
 return result;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.expense_cost_effective(t uuid, expense uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb;source jsonb;p public.payables%rowtype;x finance_private.expense_open_complement_amendments%rowtype;rev text;amount bigint;previous uuid;ordinal integer:=0;ok boolean;history jsonb:='[]';latest jsonb;
begin
 if exists(select 1 from finance_private.open_complement_extinctions closing where closing.tenant_id=t and closing.expense_id=expense) then return finance_private.expense_cost_before_open_complement(t,expense);end if;
 base:=finance_private.expense_cost_before_open_complement(t,expense);rev:=base->>'revision';amount:=(base->>'effective_amount_cents')::bigint;ok:=coalesce(base->>'verified'='true',false);
 if not exists(select 1 from finance_private.expense_open_complement_amendments a where a.tenant_id=t and a.expense_id=expense) then return base||jsonb_build_object('open_complement',null);end if;
 source:=finance_private.open_complement_source(t,expense);select * into p from public.payables where tenant_id=t and id=(base->>'payable_id')::uuid;
 for x in select * from finance_private.expense_open_complement_amendments a where a.tenant_id=t and a.expense_id=expense order by a.ordinal loop
  if x.ordinal<>ordinal+1 or x.previous_id is distinct from previous or x.revision_before is distinct from rev or x.base_revision is distinct from base->>'revision' or x.before_cost_cents is distinct from amount or x.source_snapshot is distinct from source or source->>'verified' is distinct from 'true' or x.allocated_cents::text is distinct from source->>'allocated_cents' or x.charge_id::text is distinct from base->>'charge_id' or x.payable_id::text is distinct from base->>'payable_id'
   or (x.before_payable-array['amount','status','updated_at']) is distinct from (x.after_payable-array['amount','status','updated_at']) or coalesce(x.before_payable->>'status','') not in('pending','approved') or x.after_payable->>'id' is distinct from x.payable_id::text or x.after_payable->>'tenant_id' is distinct from t::text or x.after_payable->>'source_id' is distinct from expense::text or x.after_payable->>'source_table' is distinct from 'finance_expense_items' or x.after_payable->>'status' is distinct from 'pending' or finance_private.unloading_repair_cents(x.before_payable->'amount') is distinct from (x.before_cost_cents-x.allocated_cents)::text or finance_private.unloading_repair_cents(x.after_payable->'amount') is distinct from (x.after_cost_cents-x.allocated_cents)::text
   or not exists(select 1 from public.finance_commands c where c.tenant_id=t and c.request_id=x.request_id and c.actor_id=x.actor_id and c.action='correct_open_unloading_complement' and c.result->>'amendment_id'=x.id::text and c.payload->>'expense_id'=expense::text and c.payload->>'amount_cents'=x.after_cost_cents::text and c.payload->>'charge_id'=x.charge_id::text and c.payload->>'payable_id'=x.payable_id::text and c.result->>'request_id'=x.request_id::text and c.result#>>'{effects,cost_before_cents}'=x.before_cost_cents::text and c.result#>>'{effects,cost_after_cents}'=x.after_cost_cents::text and c.result#>>'{effects,complement_after_cents}'=(x.after_cost_cents-x.allocated_cents)::text)
   or not exists(select 1 from public.finance_events a where a.tenant_id=t and a.entity_id=expense and a.actor_id=x.actor_id and a.action='unloading_open_complement_corrected' and a.after_data->>'amendment_id'=x.id::text and a.after_data#>>'{effects,cost_after_cents}'=x.after_cost_cents::text and a.before_data#>'{_evidence,source}'=x.source_snapshot)
  then ok:=false;end if;
  rev:=md5(jsonb_build_object('previous',rev,'event',to_jsonb(x))::text);amount:=x.after_cost_cents;previous:=x.id;ordinal:=x.ordinal;
  latest:=jsonb_build_object('id',x.id,'ordinal',x.ordinal,'previous_id',x.previous_id,'request_id',x.request_id,'actor_id',x.actor_id,'actor_name',x.actor_name,'reason',x.reason,'created_at',x.created_at,'cost_before_cents',x.before_cost_cents::text,'cost_after_cents',x.after_cost_cents::text,'complement_before_cents',(x.before_cost_cents-x.allocated_cents)::text,'complement_after_cents',(x.after_cost_cents-x.allocated_cents)::text,'allocated_reserved_cents',x.allocated_cents::text,'approval_reset',x.before_payable->>'status'='approved','revision_after',rev);history:=history||jsonb_build_array(latest);
 end loop;
 if p.id is null or finance_private.unloading_repair_cents(to_jsonb(p)->'amount') is distinct from (amount-(source->>'allocated_cents')::bigint)::text or p.source_table is distinct from 'finance_expense_items' or p.source_id is distinct from expense or (to_jsonb(p)-array['amount','status','updated_at','paid_amount','paid_at','bank_account_id','approved_at','approved_by']) is distinct from (x.after_payable-array['amount','status','updated_at','paid_amount','paid_at','bank_account_id','approved_at','approved_by']) then ok:=false;end if;
 return base||jsonb_build_object('verified',ok,'issue',case when ok then null else 'finance_open_complement_chain_invalid' end,'effective_amount_cents',case when ok then amount::text end,'revision',rev,'open_complement',latest||jsonb_build_object('history',history));
end$function$
;

CREATE OR REPLACE FUNCTION public.approve_payroll_period(_period_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$<<finance_payroll_lifecycle_guard>>
BEGIN
perform finance_private.lock_payroll_lifecycle((select tenant_id from public.payroll_periods where id=_period_id),_period_id,null,'approve');
<<finance_entry_guard>>
BEGIN
 PERFORM finance_private.require_access((select financial_scope.tenant_id from public.payroll_periods financial_scope where financial_scope.id=_period_id));
 <<legacy_financial_body>>

DECLARE
  _tenant uuid;
  _pstart date;
  _pend date;
  _entry record;
  _user uuid := auth.uid();
BEGIN
  SELECT tenant_id, period_start, period_end INTO _tenant, _pstart, _pend
    FROM public.payroll_periods WHERE id = _period_id;
  IF _tenant IS NULL THEN RAISE EXCEPTION 'período não encontrado'; END IF;
  IF NOT public.is_tenant_operator_or_admin(_tenant) THEN RAISE EXCEPTION 'not authorized'; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.payroll_entries WHERE payroll_period_id = _period_id) THEN
    RAISE EXCEPTION 'período sem entradas';
  END IF;

  PERFORM finance_private.assert_payroll_carryovers(_tenant,_period_id);
  PERFORM finance_private.assert_payroll_employee_advances(_tenant,_period_id);
  INSERT INTO public.payroll_generation_issues(tenant_id, payroll_period_id, issue_type, severity,
    driver_id, source_table, source_id, message)
  SELECT _tenant, _period_id, 'settlement_paid_outside_payroll', 'warning',
    ds.driver_id, 'driver_settlements', ds.id,
    'Acerto ' || substring(ds.id::text,1,8) || ' já possui pagamentos externos fora desta folha'
  FROM public.driver_settlements ds
  WHERE ds.tenant_id = _tenant
    AND EXISTS (
      SELECT 1 FROM public.payroll_entry_items i
      WHERE i.payroll_period_id = _period_id
        AND i.source_table = 'driver_settlements' AND i.source_id = ds.id
    )
    AND EXISTS (
      SELECT 1 FROM public.driver_settlement_payments dsp
      WHERE dsp.settlement_id = ds.id AND dsp.paid_at IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.payroll_entry_items ii
          WHERE ii.payroll_period_id = _period_id
            AND ii.source_table = 'driver_settlement_payments' AND ii.source_id = dsp.id
        )
    );

  if exists(select 1 from public.payroll_generation_issues where payroll_period_id=_period_id and not resolved) then
    raise exception 'finance_payroll_unresolved_generation_issues' using errcode='23514';
  end if;

  FOR _entry IN SELECT id FROM public.payroll_entries WHERE payroll_period_id = _period_id AND status IN ('draft','calculated') ORDER BY id LOOP
    PERFORM public.recompute_payroll_entry_totals(_entry.id);
  END LOOP;
  UPDATE public.payroll_entry_items SET locked = true WHERE payroll_period_id = _period_id AND EXISTS(SELECT 1 FROM public.payroll_entries e WHERE e.id=payroll_entry_items.payroll_entry_id AND e.status IN ('draft','calculated'));
  UPDATE public.payroll_entries SET status = 'approved' WHERE payroll_period_id = _period_id AND status <> 'cancelled';

  FOR _entry IN
    SELECT e.id, e.employee_id, e.driver_id, e.amount_to_pay, emp.name AS employee_name
    FROM public.payroll_entries e
    JOIN public.employees emp ON emp.id = e.employee_id
    WHERE e.payroll_period_id = _period_id
      AND e.amount_to_pay > 0
      AND e.status <> 'cancelled'
  LOOP
    INSERT INTO public.payables(tenant_id, supplier_name, category, description, amount,
      competence_date, due_date, driver_id, status, created_by,
      source_table, source_id, source_metadata, notes)
    VALUES (_tenant, _entry.employee_name, 'payroll',
      'Folha ' || to_char(_pstart,'DD/MM/YYYY') || '–' || to_char(_pend,'DD/MM/YYYY') || ' — ' || _entry.employee_name,
      _entry.amount_to_pay, _pstart, _pend, _entry.driver_id, 'pending', _user,
      'payroll_entries', _entry.id,
      jsonb_build_object('payroll_period_id', _period_id, 'employee_id', _entry.employee_id),
      NULL)
    ON CONFLICT (tenant_id, source_table, source_id, category)
      WHERE source_table IS NOT NULL AND source_id IS NOT NULL
      DO NOTHING;
  END LOOP;

  UPDATE public.payroll_periods
     SET status = 'approved', approved_by = _user, approved_at = now(), updated_at = now()
   WHERE id = _period_id;
END;

END;

END finance_payroll_lifecycle_guard;$function$
;

CREATE OR REPLACE FUNCTION public.list_available_loads_for_settlement_v2(_tenant_id uuid, _driver_id uuid DEFAULT NULL::uuid, _search text DEFAULT NULL::text, _include_settlement_id uuid DEFAULT NULL::uuid, _page integer DEFAULT 1, _page_size integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_page integer:=greatest(coalesce(_page,1),1); v_size integer:=greatest(1,least(coalesce(_page_size,100),200)); v_total bigint; v_rows jsonb;
begin
  if not public.is_tenant_operator_or_admin(_tenant_id) then raise exception 'permission_denied' using errcode='42501'; end if;
  with eligible as (
    select l.id,l.load_number,l.origin,l.destination,l.status,l.total_weight_kg,l.total_pallet_count,l.gross_cargo_value,l.freight_amount,
      l.invoice_count,l.load_date,l.driver_id,d.name driver_name,v.plate vehicle_plate,l.created_at
    from public.loads l left join public.drivers d on d.id=l.driver_id left join public.vehicles v on v.id=l.vehicle_id
    where l.tenant_id=_tenant_id and l.driver_id is not null and (_driver_id is null or l.driver_id=_driver_id)
      and (nullif(btrim(_search),'') is null or l.load_number ilike '%'||_search||'%' or l.origin ilike '%'||_search||'%' or l.destination ilike '%'||_search||'%' or l.external_load_number ilike '%'||_search||'%')
      and public._load_available_for_settlement(_tenant_id,l.id,_include_settlement_id)
  ) select count(*) into v_total from eligible;
  with eligible as (
    select l.id,l.load_number,l.origin,l.destination,l.status,l.total_weight_kg,l.total_pallet_count,l.gross_cargo_value,l.freight_amount,
      l.invoice_count,l.load_date,l.driver_id,d.name driver_name,v.plate vehicle_plate,l.created_at
    from public.loads l left join public.drivers d on d.id=l.driver_id left join public.vehicles v on v.id=l.vehicle_id
    where l.tenant_id=_tenant_id and l.driver_id is not null and (_driver_id is null or l.driver_id=_driver_id)
      and (nullif(btrim(_search),'') is null or l.load_number ilike '%'||_search||'%' or l.origin ilike '%'||_search||'%' or l.destination ilike '%'||_search||'%' or l.external_load_number ilike '%'||_search||'%')
      and public._load_available_for_settlement(_tenant_id,l.id,_include_settlement_id)
  ) select coalesce(jsonb_agg(to_jsonb(x)-'created_at'),'[]'::jsonb) into v_rows from (
    select * from eligible order by load_date desc nulls last,created_at desc,id limit v_size offset (v_page-1)*v_size
  ) x;
  return jsonb_build_object('rows',v_rows,'total',v_total,'page',v_page,'page_size',v_size);
end $function$
;

CREATE OR REPLACE FUNCTION private.request_tenant_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_headers jsonb;
  v_header_raw text;
  v_claim_raw text;
  v_raw text;
begin
  begin
    v_headers := nullif(current_setting('request.headers', true), '')::jsonb;
  exception
    when invalid_text_representation then
      raise exception 'tenant_context_invalid_headers' using errcode = '22023';
  end;

  v_header_raw := nullif(btrim(v_headers ->> 'x-agvlog-tenant-id'), '');
  v_claim_raw := nullif(btrim(auth.jwt() ->> 'active_tenant_id'), '');

  if v_header_raw is not null and v_claim_raw is not null and v_header_raw <> v_claim_raw then
    raise exception 'tenant_context_claim_mismatch' using errcode = '42501';
  end if;

  if coalesce(auth.jwt() ->> 'role', '') = 'authenticated' and v_claim_raw is null then
    raise exception 'tenant_context_claim_required' using errcode = '42501';
  end if;

  v_raw := coalesce(v_header_raw, v_claim_raw);
  if v_raw is null then
    raise exception 'tenant_context_required' using errcode = '22023';
  end if;

  begin
    return v_raw::uuid;
  exception
    when invalid_text_representation then
      raise exception 'tenant_context_invalid' using errcode = '22023';
  end;
end;
$function$
;

CREATE OR REPLACE FUNCTION finance_private.process_fiscal_observation(_tenant uuid, _observation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<projection>>
declare o public.finance_fiscal_observations%rowtype;j public.finance_fiscal_projection_jobs%rowtype;
 e public.hub_fiscal_emissions%rowtype;origin public.finance_fiscal_receivable_origins%rowtype;r public.receivables%rowtype;
 s jsonb;basis jsonb;result jsonb;before_origin jsonb;identity text;job_state text:='applied';issue text;paid numeric;title uuid;origin_id uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('fiscal:'||_tenant::text,0));
 perform pg_advisory_xact_lock(hashtextextended(_tenant::text||':finance',0));
 select * into j from public.finance_fiscal_projection_jobs where observation_id=_observation and tenant_id=_tenant for update;
 if not found then raise exception 'finance_fiscal_job_not_found' using errcode='22023';end if;
 if j.status in('applied','superseded') and j.result is not null then return j.result;end if;
 select * into o from public.finance_fiscal_observations where id=_observation and tenant_id=_tenant;
 s:=o.snapshot;
 select * into e from public.hub_fiscal_emissions where id=o.emission_id and tenant_id=_tenant for share;
 if not found then raise exception 'finance_fiscal_emission_not_found' using errcode='22023';end if;
 -- Do not materialize an obsolete authorization after a newer cancellation.
 if e.status is distinct from s->>'status' or to_jsonb(e)->>'dispatch_state' is distinct from 'recorded'
  or e.environment is distinct from s->>'environment' or e.doc_type is distinct from s->>'doc_type'
  or e.access_key is distinct from s->>'access_key' or e.authorization_protocol is distinct from s->>'authorization_protocol'
  or e.cte_document_id::text is distinct from s->>'cte_document_id' or e.fiscal_document_id::text is distinct from s->>'fiscal_document_id'
  or e.nfse_document_id::text is distinct from s->>'nfse_document_id'
  or to_jsonb(e)->'provider_document_version' is distinct from s->'provider_document_version'
  or md5(coalesce(e.request_payload,'{}')::text) is distinct from s->>'request_payload_hash' then
  job_state:='superseded';issue:='newer_fiscal_state';
 else
  select * into origin from public.finance_fiscal_receivable_origins where tenant_id=_tenant and emission_id=e.id for update;
  before_origin:=case when origin.id is null then null else to_jsonb(origin) end;origin_id:=origin.id;
  if e.status in('authorized','cancel_rejected') then
   basis:=finance_private.fiscal_receivable_basis_internal(_tenant,_observation);
   identity:=case when e.doc_type='cte' then e.access_key else nullif(e.hub_document_id,'') end;
   if not coalesce((basis->>'ready')::boolean,false) then job_state:='review';issue:=array_to_string(array(select jsonb_array_elements_text(basis->'issues')),',');
   elsif identity is null then job_state:='review';issue:='fiscal_identity_missing';
   elsif not exists(select 1 from public.clients where tenant_id=_tenant and id=(basis->>'payer_id')::uuid and active for share) then
    job_state:='review';issue:='payer_unavailable';
   else
    if origin.id is null then
     select * into origin from public.finance_fiscal_receivable_origins where tenant_id=_tenant and doc_type=e.doc_type
      and (source_id=(projection.basis->>'source_id')::uuid or fiscal_identity=identity) for update;
     before_origin:=case when origin.id is null then null else to_jsonb(origin) end;origin_id:=origin.id;
    end if;
    if origin.id is not null then
     if origin.state in('cancelled','credit_pending') or origin.emission_id<>e.id or origin.fiscal_identity<>identity or origin.source_id<>(basis->>'source_id')::uuid
       or origin.basis->>'payer_id' is distinct from basis->>'payer_id'
       or origin.basis->>'amount_cents' is distinct from basis->>'amount_cents' then
      job_state:='review';issue:='fiscal_origin_changed';
     else
      update public.finance_fiscal_receivable_origins set state='active',observation_id=_observation,updated_at=clock_timestamp() where id=origin.id;
      title:=origin.receivable_id;
     end if;
    elsif exists(select 1 from public.receivables where tenant_id=_tenant and
      ((e.cte_document_id is not null and cte_document_id=e.cte_document_id) or (e.fiscal_document_id is not null and fiscal_document_id=e.fiscal_document_id))) then
     job_state:='review';issue:='existing_receivable_requires_adoption';
    else
     -- No payment is inferred. Due date remains unknown until commercial terms
     -- are supplied; a document date is not a contractual due date.
     insert into public.receivables(tenant_id,client_id,cte_document_id,fiscal_document_id,description,amount,status,received_amount,created_by)
     values(_tenant,(basis->>'payer_id')::uuid,e.cte_document_id,e.fiscal_document_id,
      case when e.doc_type='cte' then 'CT-e ' else 'NFS-e ' end||coalesce(e.number,identity),
      (basis->>'amount_cents')::numeric/100,'pending',0,auth.uid()) returning id into title;
     insert into public.finance_fiscal_receivable_origins(tenant_id,doc_type,source_id,fiscal_identity,emission_id,receivable_id,observation_id,state,basis)
     values(_tenant,e.doc_type,(projection.basis->>'source_id')::uuid,identity,e.id,title,_observation,'active',projection.basis) returning id into origin_id;
    end if;
   end if;
  elsif origin.id is not null then
   title:=origin.receivable_id;
   if e.status='cancel_processing' then
    update public.finance_fiscal_receivable_origins set state='suspended',observation_id=_observation,updated_at=clock_timestamp() where id=origin.id;
   elsif e.status in('cancelled','rejected','denied','inutilized') then
    if e.status='cancelled' and not exists(select 1 from public.receivables credit_target where credit_target.id=origin.receivable_id and (credit_target.client_invoice_id is not null or credit_target.closing_report_id is not null)) and not exists(select 1 from public.client_invoices where tenant_id=_tenant and receivable_id=origin.receivable_id) and not exists(select 1 from public.closing_reports where tenant_id=_tenant and receivable_id=origin.receivable_id) then perform finance_private.release_receivable_customer_credits(_tenant,title,'Liberação por cancelamento fiscal confirmado',_observation);end if; select * into r from public.receivables where id=title and tenant_id=_tenant for update;
    select coalesce(sum(p.amount),0) into paid from public.receivables_payments p where p.tenant_id=_tenant and p.receivable_id=title
     and not exists(select 1 from public.receivable_payment_reversals rv where rv.tenant_id=_tenant and rv.payment_id=p.id) and not exists(select 1 from public.finance_receipt_allocation_corrections correction where correction.tenant_id=p.tenant_id and correction.payment_id=p.id)
     and not exists(select 1 from public.finance_customer_credits credit where credit.tenant_id=_tenant and credit.payment_id=p.id);
    if paid<>0 or coalesce(r.received_amount,0)<>0 then
     issue:=finance_private.release_cancelled_receipts(_tenant,origin.id,_observation);
     if issue is null then
      update public.finance_fiscal_receivable_origins set state='cancelled',observation_id=_observation,updated_at=clock_timestamp() where id=origin.id;
     else
      job_state:='review';
      update public.finance_fiscal_receivable_origins set state=case when issue='cancelled_document_in_billing_group' then 'review' else 'credit_pending' end,
       observation_id=_observation,updated_at=clock_timestamp() where id=origin.id;
     end if;
    elsif r.client_invoice_id is not null or r.closing_report_id is not null
  or exists(select 1 from public.client_invoices where tenant_id=_tenant and receivable_id=r.id)
  or exists(select 1 from public.closing_reports where tenant_id=_tenant and receivable_id=r.id) then
     job_state:='review';issue:='cancelled_document_in_billing_group';
     update public.finance_fiscal_receivable_origins set state='review',observation_id=_observation,updated_at=clock_timestamp() where id=origin.id;
    else
     update public.receivables set status='cancelled',updated_at=now() where id=title and tenant_id=_tenant;
     update public.finance_fiscal_receivable_origins set state='cancelled',observation_id=_observation,updated_at=clock_timestamp() where id=origin.id;
    end if;
   end if;
  elsif exists(select 1 from public.receivables where tenant_id=_tenant and
    ((e.cte_document_id is not null and cte_document_id=e.cte_document_id) or (e.fiscal_document_id is not null and fiscal_document_id=e.fiscal_document_id))) then
   job_state:='review';issue:='existing_receivable_requires_adoption';
  end if;
 end if;
 if job_state='review' and origin_id is not null then
  update public.finance_fiscal_receivable_origins set state='review',updated_at=clock_timestamp()
   where id=origin_id and state not in('cancelled','credit_pending');
 end if;
 result:=jsonb_build_object('version',1,'tenant_id',_tenant,'observation_id',_observation,'status',job_state,'issue',issue,'origin_id',origin_id,'receivable_id',title,'basis',basis);
 update public.finance_fiscal_projection_jobs set status=job_state,issue=projection.issue,result=projection.result,attempts=attempts+1,updated_at=clock_timestamp()
 where observation_id=_observation and tenant_id=_tenant;
 insert into public.finance_fiscal_projection_events(tenant_id,observation_id,origin_id,actor_id,action,before_data,after_data)
 values(_tenant,_observation,projection.origin_id,auth.uid(),job_state,before_origin,projection.result);
 return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION finance_private.release_cancelled_receipts(_tenant uuid, _origin uuid, _observation uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare origin public.finance_fiscal_receivable_origins%rowtype;r public.receivables%rowtype;paid numeric;valid boolean;
begin
 select * into origin from public.finance_fiscal_receivable_origins where id=_origin and tenant_id=_tenant for update;
 if not found then return 'fiscal_origin_missing';end if;
 if not exists(select 1 from public.hub_fiscal_emissions e where e.id=origin.emission_id and e.tenant_id=_tenant and e.status='cancelled'
   and e.environment='production' and to_jsonb(e)->>'dispatch_state'='recorded') then return 'fiscal_cancellation_not_confirmed';end if;
 select * into r from public.receivables where id=origin.receivable_id and tenant_id=_tenant for update;
 if not found or r.client_id is distinct from (origin.basis->>'payer_id')::uuid then return 'credit_payer_mismatch';end if;
 if r.client_invoice_id is not null or r.closing_report_id is not null
  or exists(select 1 from public.client_invoices where tenant_id=_tenant and receivable_id=r.id)
  or exists(select 1 from public.closing_reports where tenant_id=_tenant and receivable_id=r.id) then return 'cancelled_document_in_billing_group';end if;
 select coalesce(sum(p.amount),0),coalesce(bool_and(p.amount>0 and p.amount=trunc(p.amount,2) and p.amount<=999999999999.99
  and b.id is not null and b.amount=p.amount and b.transaction_type='credit' and b.bank_account_id=p.bank_account_id
  and exists(select 1 from public.bank_accounts a where a.tenant_id=_tenant and a.id=p.bank_account_id)
  and not exists(select 1 from public.receivables_payments other where other.bank_transaction_id=p.bank_transaction_id and other.id<>p.id)),false)
 into paid,valid from public.receivables_payments p left join public.bank_transactions b on b.id=p.bank_transaction_id and b.tenant_id=_tenant
 where p.tenant_id=_tenant and p.receivable_id=r.id
  and not exists(select 1 from public.receivable_payment_reversals rv where rv.tenant_id=_tenant and rv.payment_id=p.id) and not exists(select 1 from public.finance_receipt_allocation_corrections correction where correction.tenant_id=p.tenant_id and correction.payment_id=p.id)
  and not exists(select 1 from public.finance_customer_credits credit where credit.tenant_id=_tenant and credit.payment_id=p.id);
 if not valid or paid<=0 or paid>r.amount or paid is distinct from r.received_amount then return 'financial_receipt_evidence_mismatch';end if;
 insert into public.finance_customer_credits(tenant_id,payer_id,origin_id,receivable_id,payment_id,bank_transaction_id,observation_id,amount_cents,receipt_snapshot,created_by)
 select _tenant,r.client_id,origin.id,r.id,p.id,p.bank_transaction_id,_observation,(p.amount*100)::bigint,to_jsonb(p),auth.uid()
 from public.receivables_payments p where p.tenant_id=_tenant and p.receivable_id=r.id
  and not exists(select 1 from public.receivable_payment_reversals rv where rv.tenant_id=_tenant and rv.payment_id=p.id) and not exists(select 1 from public.finance_receipt_allocation_corrections correction where correction.tenant_id=p.tenant_id and correction.payment_id=p.id)
  and not exists(select 1 from public.finance_customer_credits credit where credit.tenant_id=_tenant and credit.payment_id=p.id);
 update public.receivables set status='cancelled',received_amount=0,received_at=null,updated_at=clock_timestamp() where id=r.id and tenant_id=_tenant;
 return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION finance_private.unloading_origin_base(_tenant uuid, _charge uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.finance_unloading_charges%rowtype;cmd public.finance_commands%rowtype;commands jsonb;events jsonb;proof boolean;
begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into c from public.finance_unloading_charges where tenant_id=_tenant and id=_charge;
 if not found then raise exception 'finance_unloading_not_found' using errcode='22023';end if;

 select coalesce(jsonb_agg(to_jsonb(x) order by request_id),'[]') into commands from public.finance_commands x where tenant_id=_tenant and action='record_unloading' and x.result->>'charge_id'=c.id::text;
 select x.* into cmd from public.finance_commands x where x.tenant_id=_tenant and x.action='record_unloading' and x.result->>'charge_id'=c.id::text order by x.request_id limit 1;
 select coalesce(jsonb_agg(to_jsonb(x) order by id),'[]') into events from public.finance_events x where tenant_id=_tenant and entity_type='unloading' and entity_id=c.id and action='recorded';
 proof:=jsonb_array_length(commands)=1 and jsonb_array_length(events)=1
  and cmd.payload->>'tenant_id'=c.tenant_id::text and cmd.result->>'tenant_id'=c.tenant_id::text
  and cmd.actor_id=c.created_by and cmd.result->>'receivable_id'=c.receivable_id::text and cmd.result->>'supplier_id'=c.supplier_id::text
  and cmd.payload->>'amount_cents'=c.amount_cents::text and cmd.payload->>'occurred_on'=c.occurred_on::text
  and ((c.receipt_path is not null and cmd.payload->>'receipt_path'=c.receipt_path) or (c.receipt_path is null and secure_upload_private.unloading_prepared_receipt_proven(c.tenant_id,c.id,cmd.payload))) and cmd.payload->>'stop_id'=c.recorded_stop_id::text
  and cmd.payload->>'expected_revision'=c.source_snapshot->>'revision'
  and c.source_snapshot->>'supplier_id'=c.supplier_id::text and c.source_snapshot->>'delivery_stop_id'=c.delivery_stop_id::text
  and events#>'{0,after_data,context}'=c.source_snapshot
  and events#>>'{0,actor_id}'=c.created_by::text and events#>>'{0,after_data,receivable_id}'=c.receivable_id::text
  and events#>>'{0,after_data,amount_cents}'=c.amount_cents::text
  and exists(select 1 from public.clients where tenant_id=_tenant and id=c.supplier_id);

 return jsonb_build_object('origin_verified',coalesce(proof,false),'receivable_id',c.receivable_id,
 'original',jsonb_build_object('supplier_id',c.supplier_id,'supplier_name',c.source_snapshot->>'supplier_name','amount_cents',c.amount_cents::text),
 '_evidence',jsonb_build_object('charge',to_jsonb(c),'commands',commands,'events',events));
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.expense_cost_before_open_complement(t uuid, expense uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare base jsonb;reg jsonb;d jsonb;ds jsonb:='[]';r finance_private.cost_disposition_returns%rowtype;m public.finance_movements%rowtype;rows jsonb;returned bigint;total_returned bigint:=0;driver_open bigint:=0;recovery_open bigint:=0;open_amount bigint;ok boolean;fingerprint text:='';
begin
 base:=finance_private.expense_cost_before_returns(t,expense);reg:=nullif(base->'regularization','null'::jsonb);if reg is null then return base;end if;ok:=base->>'verified'='true';
 for d in select value from jsonb_array_elements(reg->'dispositions') loop
  returned:=0;rows:='[]';
  for r in select * from finance_private.cost_disposition_returns x where x.tenant_id=t and x.disposition_id=(d->>'id')::uuid order by x.created_at,x.id loop
   select * into m from public.finance_movements where tenant_id=t and id=r.incoming_movement_id;
   if r.expense_id<>expense or r.regularization_id::text is distinct from reg->>'id' or r.source_snapshot->'movement' is distinct from to_jsonb(m) or r.source_snapshot->'disposition' is distinct from d or not exists(select 1 from finance_private.active_movements a where a.tenant_id=t and a.id=m.id) or finance_private.receipt_movement_used_cents(t,m.id)>m.amount_cents
    or not exists(select 1 from public.finance_commands c where c.tenant_id=t and c.request_id=r.request_id and c.actor_id=r.actor_id and c.action='record_cost_disposition_return' and c.payload->>'disposition_id'=r.disposition_id::text and c.payload->>'incoming_movement_id'=m.id::text and c.payload->>'amount_cents'=r.amount_cents::text and c.result->>'return_id'=r.id::text)
    or not exists(select 1 from public.finance_events e where e.tenant_id=t and e.entity_id=expense and e.actor_id=r.actor_id and e.action='cost_disposition_return_recorded' and e.after_data->>'return_id'=r.id::text)
   then ok:=false;end if;
   returned:=returned+r.amount_cents;fingerprint:=fingerprint||md5(to_jsonb(r)::text);
   rows:=rows||jsonb_build_array(jsonb_build_object('id',r.id,'request_id',r.request_id,'incoming_movement_id',r.incoming_movement_id,'amount_cents',r.amount_cents::text,'occurred_on',r.occurred_on,'actor_id',r.actor_id,'actor_name',r.actor_name,'reason',r.reason,'created_at',r.created_at));
  end loop;
  open_amount:=(d->>'residual_cents')::bigint-returned;if open_amount<0 then ok:=false;end if;total_returned:=total_returned+returned;
  if d->>'disposition_type'='driver_custody' then driver_open:=driver_open+open_amount;else recovery_open:=recovery_open+open_amount;end if;
  ds:=ds||jsonb_build_array(d||jsonb_build_object('returned_cents',returned::text,'open_cents',open_amount::text,'resolution_status',case when open_amount=0 then 'resolved' when returned>0 then 'partial' else 'pending' end,'returns',rows));
 end loop;
 if exists(select 1 from finance_private.cost_disposition_returns prior_return where prior_return.tenant_id=t and prior_return.expense_id=expense and prior_return.regularization_id::text<>reg->>'id') then ok:=false;end if;
 return base||jsonb_build_object('verified',ok,'issue',case when ok then null else 'finance_cost_return_chain_invalid' end,'effective_amount_cents',case when ok then base->>'effective_amount_cents' end,'revision',case when fingerprint='' then base->>'revision' else md5((base->>'revision')||fingerprint) end,'regularization',reg||jsonb_build_object('dispositions',ds,'returned_cents',total_returned::text,'open_cents',((reg->>'residual_cents')::bigint-total_returned)::text,'driver_custody_open_cents',driver_open::text,'payment_recovery_open_cents',recovery_open::text));
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.open_complement_source(t uuid, expense uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.finance_expense_items%rowtype;b public.finance_expense_batches%rowtype;a public.finance_expense_allocations%rowtype;m public.finance_movements%rowtype;command public.finance_commands%rowtype;item jsonb;allocations jsonb:='[]';movements jsonb:='[]';total numeric:=0;ok boolean:=true;
begin
 perform finance_private.require_access(t);select * into e from public.finance_expense_items where tenant_id=t and id=expense;select * into b from public.finance_expense_batches where tenant_id=t and id=e.batch_id;
 if e.id is null or e.unloading_id is null then raise exception 'finance_unloading_cost_source_unavailable' using errcode='22023';end if;
 select c.* into command from public.finance_commands c where c.tenant_id=t and c.action='record_expense_batch' and c.result->>'batch_id'=b.id::text;
 if (select count(*) from public.finance_commands c where c.tenant_id=t and c.action='record_expense_batch' and c.result->>'batch_id'=b.id::text)<>1 then ok:=false;end if;
 select value into item from jsonb_array_elements(case when jsonb_typeof(command.payload->'items')='array' then command.payload->'items' else '[]'::jsonb end) where value->>'id'=e.id::text;
 if item->>'amount_cents' is distinct from e.amount_cents::text or item->>'supplier_id' is distinct from e.supplier_id::text or jsonb_typeof(item->'allocations') is distinct from 'array' then ok:=false;end if;
 for a in select * from public.finance_expense_allocations x where x.tenant_id=t and x.expense_id=e.id order by x.id loop
  select * into m from public.finance_movements where tenant_id=t and id=a.movement_id;
  if m.id is null or m.direction<>'out' or m.nature='transfer' or not exists(select 1 from finance_private.active_movements x where x.tenant_id=t and x.id=m.id) or finance_private.movement_used_cents(t,m.id)>m.amount_cents or finance_private.movement_used_cents(t,m.id)<a.amount_cents then ok:=false;end if;
  if (select count(*) from jsonb_array_elements(case when jsonb_typeof(item->'allocations')='array' then item->'allocations' else '[]'::jsonb end)x where x->>'movement_id'=a.movement_id::text and x->>'amount_cents'=a.amount_cents::text)<>1 then ok:=false;end if;
  total:=total+a.amount_cents;allocations:=allocations||jsonb_build_array(to_jsonb(a));movements:=movements||jsonb_build_array(to_jsonb(m));
 end loop;
 if total<=0 or total>e.amount_cents or jsonb_array_length(allocations)<>jsonb_array_length(case when jsonb_typeof(item->'allocations')='array' then item->'allocations' else '[]'::jsonb end) then ok:=false;end if;
 return jsonb_build_object('verified',ok,'allocated_cents',trunc(total)::text,'expense',to_jsonb(e),'batch',to_jsonb(b),'allocations',allocations,'movements',movements,'command',to_jsonb(command),'item',item);
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.assert_payroll_employee_advances(t uuid, period uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item record;proof jsonb;source record;begin
 for source in select a.id,e.id entry_id from public.employee_advances a join public.payroll_entries e on e.tenant_id=t and e.employee_id=a.employee_id join public.payroll_periods p on p.tenant_id=t and p.id=e.payroll_period_id where a.tenant_id=t and p.id=period and e.status<>'cancelled' and a.advance_date between p.period_start and p.period_end loop
  proof:=finance_private.payroll_advance_payment_evidence(t,source.id);
  if (proof->>'paid_cents')::numeric>0 and not exists(select 1 from public.payroll_entry_items x where x.tenant_id=t and x.payroll_entry_id=source.entry_id and x.source_table='employee_advances' and x.source_id=source.id and x.source_metadata->'employee_advance_payment'=proof) then raise exception 'finance_payroll_advance_changed_recalculate' using errcode='40001';end if;
 end loop;
 for item in select x.*,e.employee_id expected_employee from public.payroll_entry_items x join public.payroll_entries e on e.tenant_id=t and e.id=x.payroll_entry_id where x.tenant_id=t and x.payroll_period_id=period and x.source_table='employee_advances' and e.status<>'cancelled' loop
  proof:=finance_private.payroll_advance_payment_evidence(t,item.source_id);
  if item.nature<>'already_paid' or item.item_type<>'driver_advance' or item.amount is distinct from (proof->>'paid_cents')::numeric/100 or item.source_metadata->'employee_advance_payment' is distinct from proof or item.expected_employee::text is distinct from proof->>'employee_id' then raise exception 'finance_payroll_advance_changed_recalculate' using errcode='40001';end if;
 end loop;
end$function$
;

CREATE OR REPLACE FUNCTION public.recompute_payroll_entry_totals(_entry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$<<finance_payroll_lifecycle_guard>>
BEGIN
perform finance_private.lock_payroll_lifecycle((select tenant_id from public.payroll_entries where id=_entry_id),(select payroll_period_id from public.payroll_entries where id=_entry_id),_entry_id,'edit');

DECLARE
  _gross numeric(14,2) := 0;
  _debit numeric(14,2) := 0;
  _paid  numeric(14,2) := 0;
  _net   numeric(14,2) := 0;
  _to_pay numeric(14,2) := 0;
  _carry numeric(14,2) := 0;
BEGIN
  PERFORM finance_private.refresh_payroll_employee_advances((select tenant_id from public.payroll_entries where id=_entry_id),_entry_id);
  PERFORM finance_private.refresh_payroll_carryover((select tenant_id from public.payroll_entries where id=_entry_id),_entry_id);
  SELECT COALESCE(SUM(amount) FILTER (WHERE nature='credit'),0),
         COALESCE(SUM(amount) FILTER (WHERE nature='debit'),0),
         COALESCE(SUM(amount) FILTER (WHERE nature='already_paid'),0)
    INTO _gross, _debit, _paid
  FROM public.payroll_entry_items
  WHERE payroll_entry_id = _entry_id;

  _net := _gross - _debit;
  IF _paid > _net THEN
    _carry := _paid - greatest(_net,0);
    _to_pay := 0;
  ELSE
    _carry := 0;
    _to_pay := _net - _paid;
  END IF;

  UPDATE public.payroll_entries
     SET gross_amount = _gross,
         discount_amount = _debit,
         already_paid_amount = _paid,
         net_amount = _net,
         amount_to_pay = _to_pay,
         carryover_amount = _carry,
         updated_at = now()
   WHERE id = _entry_id;
END;

END finance_payroll_lifecycle_guard;$function$
;

CREATE OR REPLACE FUNCTION finance_private.refresh_payroll_carryover(t uuid, target_entry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.payroll_entries%rowtype;p public.payroll_periods%rowtype;ctx jsonb;proof jsonb;before_item jsonb;after_item jsonb;n integer;actor_name text;begin
 perform finance_private.require_access(t);
 select * into target from public.payroll_entries where tenant_id=t and id=target_entry_id for update;
 select * into p from public.payroll_periods where tenant_id=t and id=target.payroll_period_id for update;
 if target.id is null or p.id is null then raise exception 'finance_payroll_entry_not_found' using errcode='22023';end if;
 if target.status not in('draft','calculated') or p.status not in('draft','calculated') then raise exception 'finance_payroll_period_protected' using errcode='55000';end if;
 select count(*) into n from public.payroll_entry_items i where i.tenant_id=t and i.payroll_entry_id=target.id and i.source_table='payroll_entries' and i.nature='already_paid' and i.item_type='other' and i.source_metadata ? 'payroll_carryover';
 if n>1 then raise exception 'finance_payroll_carryover_item_ambiguous' using errcode='23514';end if;
 select to_jsonb(i) into before_item from public.payroll_entry_items i where i.tenant_id=t and i.payroll_entry_id=target.id and i.source_table='payroll_entries' and i.nature='already_paid' and i.item_type='other' and i.source_metadata ? 'payroll_carryover' order by i.id limit 1;
 ctx:=finance_private.payroll_carryover_context(t,target.id);proof:=ctx->'proof';
 if ctx->'required' is distinct from 'true'::jsonb then
  delete from public.payroll_entry_items i where i.tenant_id=t and i.payroll_entry_id=target.id and i.source_table='payroll_entries' and i.nature='already_paid' and i.item_type='other' and i.source_metadata ? 'payroll_carryover';
  update public.payroll_entries set source_summary=(case when jsonb_typeof(source_summary)='object' then source_summary else '{}'::jsonb end)-'payroll_carryover' where tenant_id=t and id=target.id;
  if before_item is null then return;end if;
 else
  if before_item is null then
   insert into public.payroll_entry_items(tenant_id,payroll_period_id,payroll_entry_id,employee_id,driver_id,item_type,nature,description,amount,source_table,source_id,source_metadata,competence_date,created_by)
   values(t,p.id,target.id,target.employee_id,target.driver_id,'other','already_paid','Saldo de adiantamento transportado da competência anterior',(proof->>'amount_cents')::numeric/100,'payroll_entries',(ctx->>'source_entry_id')::uuid,jsonb_build_object('payroll_carryover',proof),p.period_start,auth.uid());
  else
   update public.payroll_entry_items set employee_id=target.employee_id,driver_id=target.driver_id,description='Saldo de adiantamento transportado da competência anterior',
    amount=(proof->>'amount_cents')::numeric/100,source_id=(ctx->>'source_entry_id')::uuid,source_metadata=jsonb_build_object('payroll_carryover',proof),competence_date=p.period_start
   where tenant_id=t and payroll_entry_id=target.id and source_table='payroll_entries' and nature='already_paid' and item_type='other' and source_metadata ? 'payroll_carryover';
  end if;
  update public.payroll_entries set source_summary=(case when jsonb_typeof(source_summary)='object' then source_summary else '{}'::jsonb end)||jsonb_build_object('payroll_carryover',proof) where tenant_id=t and id=target.id;
 end if;
 select to_jsonb(i) into after_item from public.payroll_entry_items i where i.tenant_id=t and i.payroll_entry_id=target.id and i.source_table='payroll_entries' and i.nature='already_paid' and i.item_type='other' and i.source_metadata ? 'payroll_carryover';
 if before_item is not distinct from after_item then return;end if;
 select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,auth.uid()::text) into actor_name from auth.users where id=auth.uid();
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,before_data,after_data)
 values(t,'payroll_entry',target.id,case when after_item is null then 'payroll_carryover_removed' else 'payroll_carryover_propagated' end,auth.uid(),coalesce(actor_name,auth.uid()::text),
  'Saldo de adiantamento transportado sem criar novo pagamento.',before_item,jsonb_build_object('item',after_item,'context',ctx,'cash_changed',false,'fiscal_document_created',false));
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.assert_payroll_carryovers(t uuid, period_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target public.payroll_entries%rowtype;ctx jsonb;proof jsonb;carry_item public.payroll_entry_items%rowtype;n integer;begin
 for target in select * from public.payroll_entries where tenant_id=t and payroll_period_id=period_id and status<>'cancelled' order by id loop
  ctx:=finance_private.payroll_carryover_context(t,target.id);proof:=ctx->'proof';
  select count(*) into n from public.payroll_entry_items x where x.tenant_id=t and x.payroll_entry_id=target.id and x.source_table='payroll_entries' and x.nature='already_paid' and x.item_type='other' and x.source_metadata ? 'payroll_carryover';
  select * into carry_item from public.payroll_entry_items x where x.tenant_id=t and x.payroll_entry_id=target.id and x.source_table='payroll_entries' and x.nature='already_paid' and x.item_type='other' and x.source_metadata ? 'payroll_carryover' order by x.id limit 1;
  if ctx->'required'='true'::jsonb then
   if n<>1 or carry_item.payroll_period_id is distinct from period_id or carry_item.employee_id is distinct from target.employee_id or carry_item.driver_id is distinct from target.driver_id
    or carry_item.source_id is distinct from (ctx->>'source_entry_id')::uuid or carry_item.amount is distinct from (proof->>'amount_cents')::numeric/100
    or carry_item.source_metadata->'payroll_carryover' is distinct from proof or target.source_summary->'payroll_carryover' is distinct from proof
   then raise exception 'finance_payroll_carryover_changed_recalculate' using errcode='40001';end if;
