CREATE OR REPLACE FUNCTION finance_private.customer_credit_position_before_refunds(_tenant uuid, _credit uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.finance_customer_credits%rowtype;proof jsonb;history jsonb;used numeric;released numeric;valid boolean;original numeric;
begin
 select * into c from public.finance_customer_credits where tenant_id=_tenant and id=_credit;
 if not found then raise exception 'finance_customer_credit_missing' using errcode='22023';end if;
 proof:=finance_private.customer_credit_source_evidence(_tenant,_credit);original:=c.amount_cents;
 select coalesce(sum(e.amount_cents) filter(where e.action='apply'),0),coalesce(sum(e.amount_cents) filter(where e.action='release'),0),coalesce(jsonb_agg(to_jsonb(e) order by e.created_at,e.id),'[]') into used,released,history from finance_private.customer_credit_application_events e where e.tenant_id=_tenant and e.credit_id=_credit;
 valid:=proof->'valid'='true'::jsonb and used-released between 0 and original;
 if exists(select 1 from finance_private.customer_credit_application_events e left join public.receivables r on r.tenant_id=e.tenant_id and r.id=e.receivable_id where e.tenant_id=_tenant and e.credit_id=_credit and(e.source_snapshot->>'binding_revision' is distinct from md5(to_jsonb(c)::text) or r.id is null or r.client_id is distinct from c.payer_id or not ((e.observation_id is not null and e.actor_id is null and e.action='release' and exists(select 1 from public.finance_fiscal_observations observation join public.finance_fiscal_receivable_origins origin on origin.tenant_id=observation.tenant_id and origin.emission_id=observation.emission_id where observation.tenant_id=e.tenant_id and observation.id=e.observation_id and origin.receivable_id=e.receivable_id and observation.snapshot->>'status'='cancelled' and observation.snapshot->>'environment'='production')) or (e.observation_id is null and exists(select 1 from public.finance_events audit where audit.tenant_id=e.tenant_id and audit.entity_id=e.id and audit.entity_type='customer_credit_application' and audit.action=case when e.action='apply' then 'customer_credit_applied' else 'customer_credit_application_released' end and audit.actor_id is not distinct from e.actor_id and audit.after_data->>'request_id'=e.request_id::text))))) then valid:=false;end if;
 if exists(select 1 from finance_private.customer_credit_application_events e where e.tenant_id=_tenant and e.credit_id=_credit and e.action='release' and not exists(select 1 from finance_private.customer_credit_application_events a where a.id=e.application_id and a.tenant_id=e.tenant_id and a.credit_id=e.credit_id and a.receivable_id=e.receivable_id and a.action='apply')) or exists(select 1 from finance_private.customer_credit_application_events a where a.tenant_id=_tenant and a.credit_id=_credit and a.action='apply' and (select coalesce(sum(r.amount_cents),0) from finance_private.customer_credit_application_events r where r.application_id=a.id and r.action='release')>a.amount_cents) then valid:=false;end if;
 return jsonb_build_object('version',1,'tenant_id',_tenant,'credit_id',_credit,'payer_id',c.payer_id,'valid',coalesce(valid,false),'original_cents',original::text,'applied_cents',case when valid then (used-released)::text end,'released_cents',released::text,'available_cents',case when valid then (original-used+released)::text end,'binding_revision',md5(to_jsonb(c)::text),'source_revision',proof->'source_revision','revision',md5(jsonb_build_object('proof',proof,'events',history)::text),'history',history);
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.customer_refund_movement_origin(_tenant uuid, _movement uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.finance_movements%rowtype;c public.finance_commands%rowtype;e public.finance_events%rowtype;
 commands jsonb;events jsonb;snapshot jsonb;p jsonb;issue text;expected jsonb;
begin

 select * into m from public.finance_movements where tenant_id=_tenant and id=_movement;
 if not found then raise exception 'finance_movement_not_found' using errcode='22023';end if;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.request_id),'[]'::jsonb) into commands
 from public.finance_commands x where x.tenant_id=_tenant and x.action='record_movement' and finance_private.movement_origin_uuid(x.result->>'movement_id')=_movement;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]'::jsonb) into events
 from public.finance_events x where x.tenant_id=_tenant and x.entity_type='movement' and x.entity_id=_movement and x.action='recorded';
 snapshot:=jsonb_build_object('movement',to_jsonb(m),'recording_commands',commands,'recording_events',events);
 if jsonb_array_length(commands)=0 then issue:='recording_origin_unproven';
 elsif jsonb_array_length(commands)<>1 then issue:='recording_origin_ambiguous';
 else
  select * into c from public.finance_commands where tenant_id=_tenant and request_id=(commands->0->>'request_id')::uuid;
  p:=c.payload;
  if c.actor_id is distinct from m.created_by or jsonb_typeof(p) is distinct from 'object'
   or exists(select 1 from jsonb_object_keys(case when jsonb_typeof(p)='object' then p else '{}'::jsonb end) k
    where k not in('version','tenant_id','request_id','bank_account_id','direction','nature','amount_cents','occurred_on',
     'description','beneficiary_name','beneficiary_document','driver_id','bank_reference','receipt_path','reason'))
   or p->>'version' is distinct from '1' or finance_private.movement_origin_uuid(p->>'tenant_id') is distinct from _tenant or finance_private.movement_origin_uuid(p->>'request_id') is distinct from c.request_id
   or c.result @> jsonb_build_object('version',1,'tenant_id',_tenant,'request_id',c.request_id,'movement_id',_movement,'confirmed',true) is distinct from true
   or finance_private.movement_origin_uuid(p->>'bank_account_id') is distinct from m.bank_account_id
   or p->>'direction' is distinct from m.direction or p->>'nature' is distinct from m.nature
   or p->>'occurred_on' is distinct from m.occurred_on::text
   or btrim(p->>'description') is distinct from m.description
   or btrim(p->>'beneficiary_name') is distinct from m.beneficiary_name
   or nullif(btrim(p->>'beneficiary_document'),'') is distinct from m.beneficiary_document
   or finance_private.movement_origin_uuid(nullif(p->>'driver_id','')) is distinct from m.driver_id
   or (nullif(p->>'driver_id','') is not null and finance_private.movement_origin_uuid(p->>'driver_id') is null)
   or nullif(btrim(p->>'bank_reference'),'') is distinct from m.bank_reference
   or nullif(btrim(p->>'receipt_path'),'') is distinct from m.receipt_path
  then issue:='recording_origin_mismatch';
  elsif coalesce(p->>'amount_cents','') !~ '^[0-9]{1,14}$' then issue:='recording_origin_mismatch';
  elsif (p->>'amount_cents')::numeric<>m.amount_cents then issue:='recording_origin_mismatch';
  elsif jsonb_array_length(events)<>1 then issue:='recording_event_unproven';
  else
   select * into e from public.finance_events where tenant_id=_tenant and id=(events->0->>'id')::uuid;
   expected:=jsonb_build_object('id',m.id,'tenant_id',m.tenant_id,'bank_account_id',m.bank_account_id,
    'direction',m.direction,'nature',m.nature,'amount_cents',m.amount_cents,'occurred_on',m.occurred_on,
    'description',m.description,'beneficiary_name',m.beneficiary_name,'beneficiary_document',m.beneficiary_document,
    'driver_id',m.driver_id,'bank_reference',m.bank_reference,'receipt_path',m.receipt_path,'created_by',m.created_by);
   if e.actor_id is distinct from c.actor_id or e.reason is distinct from btrim(p->>'reason')
    or e.after_data @> expected is distinct from true then issue:='recording_event_mismatch';end if;
  end if;
 end if;
 return jsonb_build_object('version',1,'tenant_id',_tenant,'movement_id',_movement,
  'verified',issue is null,'issue',issue,'original_request_id',c.request_id,
  'revision',md5(snapshot::text),'snapshot',snapshot);
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.payroll_carryover_item_chain(t uuid, item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare carry_item public.payroll_entry_items%rowtype;target public.payroll_entries%rowtype;target_period public.payroll_periods%rowtype;
 source public.payroll_entries%rowtype;source_period public.payroll_periods%rowtype;proof jsonb;issue text;snapshot jsonb;begin
 select * into carry_item from public.payroll_entry_items where tenant_id=t and id=item_id;
 select * into target from public.payroll_entries where tenant_id=t and id=carry_item.payroll_entry_id;
 select * into target_period from public.payroll_periods where tenant_id=t and id=target.payroll_period_id;
 select * into source from public.payroll_entries where tenant_id=t and id=carry_item.source_id;
 select * into source_period from public.payroll_periods where tenant_id=t and id=source.payroll_period_id;
 if source.id is not null then proof:=finance_private.payroll_carryover_evidence(t,source.id);end if;
 if carry_item.id is null or carry_item.item_type<>'other' or carry_item.nature<>'already_paid' or carry_item.source_table<>'payroll_entries' or not(carry_item.source_metadata ? 'payroll_carryover') then issue:='paid_projection_carryover_source_missing';
 elsif target.id is null or target_period.id is null or source.id is null or source_period.id is null then issue:='paid_projection_carryover_parent_missing';
 elsif target.employee_id is distinct from source.employee_id or carry_item.employee_id is distinct from target.employee_id or target.driver_id is distinct from source.driver_id or carry_item.driver_id is distinct from target.driver_id then issue:='paid_projection_carryover_employee_mismatch';
 elsif source_period.period_end+1 is distinct from target_period.period_start then issue:='paid_projection_carryover_period_mismatch';
 elsif proof->'valid' is distinct from 'true'::jsonb or coalesce((proof->>'amount_cents')::bigint,0)<=0 then issue:='paid_projection_carryover_parent_unresolved';
 elsif carry_item.amount is distinct from (proof->>'amount_cents')::numeric/100 or carry_item.source_metadata->'payroll_carryover' is distinct from proof then issue:='paid_projection_carryover_snapshot_changed';end if;
 snapshot:=jsonb_build_object('item',to_jsonb(carry_item),'target_entry',to_jsonb(target),'target_period',to_jsonb(target_period),'source_entry',to_jsonb(source),'source_period',to_jsonb(source_period),'stored',carry_item.source_metadata->'payroll_carryover','current',proof);
 return jsonb_build_object('valid',issue is null,'issue',issue,'footprints',coalesce(proof->'footprints','[]'::jsonb),'snapshot',snapshot,'revision',md5(snapshot::text));
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.customer_credit_source_evidence(_tenant uuid, _credit uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.finance_customer_credits%rowtype;source jsonb;valid boolean;
begin

 select * into c from public.finance_customer_credits where tenant_id=_tenant and id=_credit;
 if not found then raise exception 'finance_credit_not_found' using errcode='22023';end if;
  select jsonb_build_object('credit',to_jsonb(c),'payment',to_jsonb(payment_row),'bank',to_jsonb(bank_row),'reversals',(select coalesce(jsonb_agg(to_jsonb(rv) order by id),'[]') from public.receivable_payment_reversals rv where rv.tenant_id=_tenant and rv.payment_id=c.payment_id),'corrections',(select coalesce(jsonb_agg(to_jsonb(x) order by id),'[]') from public.finance_receipt_allocation_corrections x where x.tenant_id=_tenant and x.payment_id=c.payment_id)) into source from public.receivables_payments payment_row left join public.bank_transactions bank_row on bank_row.tenant_id=payment_row.tenant_id and bank_row.id=c.bank_transaction_id where payment_row.tenant_id=_tenant and payment_row.id=c.payment_id;
  valid:=source is not null and source#>>'{payment,receivable_id}'=c.receivable_id::text and source#>>'{payment,bank_transaction_id}'=c.bank_transaction_id::text and source#>>'{bank,transaction_type}'='credit' and source#>>'{payment,bank_account_id}'=source#>>'{bank,bank_account_id}' and coalesce((source#>>'{payment,amount}')::numeric*100=c.amount_cents,false) and coalesce((source#>>'{bank,amount}')::numeric*100=c.amount_cents,false) and source->'reversals'='[]'::jsonb and source->'corrections'='[]'::jsonb and c.receipt_snapshot->>'id'=c.payment_id::text and c.receipt_snapshot->>'tenant_id'=_tenant::text and c.receipt_snapshot->>'receivable_id'=c.receivable_id::text and c.receipt_snapshot->>'bank_transaction_id'=c.bank_transaction_id::text
   and not exists(select 1 from public.receivables_payments other where other.tenant_id=_tenant and other.bank_transaction_id=c.bank_transaction_id and other.id<>c.payment_id)
   and exists(select 1 from public.finance_fiscal_receivable_origins o join public.receivables credited_title on credited_title.tenant_id=o.tenant_id and credited_title.id=o.receivable_id join public.finance_fiscal_observations observation on observation.tenant_id=o.tenant_id and observation.emission_id=o.emission_id and observation.id=c.observation_id where o.tenant_id=_tenant and o.id=c.origin_id and o.receivable_id=c.receivable_id and o.basis->>'payer_id'=c.payer_id::text and o.state='cancelled' and credited_title.status='cancelled');
  valid:=coalesce(valid,false);
  source:=jsonb_build_object('credit',to_jsonb(c),'proof',source,'origin',(select to_jsonb(o) from public.finance_fiscal_receivable_origins o where o.tenant_id=_tenant and o.id=c.origin_id),'observation',(select to_jsonb(o) from public.finance_fiscal_observations o where o.tenant_id=_tenant and o.id=c.observation_id));
 return jsonb_build_object('credit_id',c.id,'payer_id',c.payer_id,'source_payment_id',c.payment_id,'source_revision',md5(coalesce(source,'null'::jsonb)::text),'amount_cents',case when valid then c.amount_cents::text end,'valid',valid);
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.receivable_credit_evidence(_tenant uuid, _receivable uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare total numeric;valid boolean:=true;c record;position jsonb;history jsonb;
begin
 select coalesce(sum(case when action='apply' then amount_cents else -amount_cents end),0),coalesce(jsonb_agg(to_jsonb(e) order by created_at,id),'[]') into total,history from finance_private.customer_credit_application_events e where tenant_id=_tenant and receivable_id=_receivable;
 for c in select distinct credit_id from finance_private.customer_credit_application_events where tenant_id=_tenant and receivable_id=_receivable loop
  position:=finance_private.customer_credit_position(_tenant,c.credit_id);if position->'valid' is distinct from 'true'::jsonb then valid:=false;end if;
 end loop;
 if total<0 then valid:=false;end if;
 return jsonb_build_object('valid',valid,'declared_applied_cents',total::text,'applied_cents',case when valid then total::text end,'history',history,'revision',md5(history::text));
end$function$
;

CREATE OR REPLACE FUNCTION public._lock_receivable_financial_graph(_tenant uuid, _id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_invoice uuid;begin
 perform pg_advisory_xact_lock(hashtextextended('fiscal:'||_tenant::text,0));
 select client_invoice_id into v_invoice from public.receivables where tenant_id=_tenant and id=_id;
 perform id from public.closing_reports where tenant_id=_tenant and (receivable_id=_id or client_invoice_id=v_invoice) order by id for update nowait;
 perform id from public.client_invoices where tenant_id=_tenant and (id=v_invoice or receivable_id=_id) order by id for update nowait;
 perform id from public.receivables where tenant_id=_tenant and id=_id for update nowait;
 if not found then raise exception 'financial_receivable_not_found' using errcode='23514';end if;
end;$function$
;

CREATE OR REPLACE FUNCTION finance_private.receivable_installment_position(_tenant uuid, _receivable uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.receivables%rowtype;e finance_private.receivable_agreement_events%rowtype;s jsonb;rows jsonb:='[]';agreement uuid;status text:='none';scheduled numeric:=0;unallocated numeric;open_value numeric;valid boolean:=true;requires boolean:=false;history_count bigint;rev text;
begin
 perform finance_private.require_access(_tenant);select * into r from public.receivables where tenant_id=_tenant and id=_receivable;
 if not found then raise exception 'finance_agreement_receivable_missing' using errcode='22023';end if;
 s:=public._receivable_financial_snapshot(_tenant,_receivable);open_value:=(s->>'open_cents')::numeric;
 select count(*) into history_count from finance_private.receivable_agreement_events where tenant_id=_tenant and receivable_id=_receivable;
 select * into e from finance_private.receivable_agreement_current(_tenant,_receivable);
 if found then
  if e.action='revoke' then status:='revoked';
  else agreement:=e.agreement_id;status:=case when r.status='cancelled' then 'source_blocked' else 'active' end;
   with values_by_installment as(
    select i.*,coalesce(sum(case when a.action='allocate' then a.amount_cents else -a.amount_cents end)filter(where a.kind='cash'),0) cash,
     coalesce(sum(case when a.action='allocate' then a.amount_cents else -a.amount_cents end)filter(where a.kind='credit'),0) credit,
     coalesce(sum(case when a.action='allocate' then a.amount_cents else -a.amount_cents end)filter(where a.kind='discount'),0) discount,
     coalesce(sum(case when a.action='allocate' then a.amount_cents else -a.amount_cents end)filter(where a.kind='loss'),0) loss
    from finance_private.receivable_agreement_installments i left join finance_private.receivable_installment_allocations a on a.tenant_id=i.tenant_id and a.installment_id=i.id
    where i.tenant_id=_tenant and i.receivable_id=_receivable and i.agreement_id=agreement group by i.tenant_id,i.receivable_id,i.agreement_id,i.id,i.ordinal,i.amount_cents,i.due_on
   ),checked as(select *,amount_cents-cash-credit-discount-loss open_cents from values_by_installment)
   select coalesce(jsonb_agg(jsonb_build_object('id',id,'agreement_id',agreement_id,'ordinal',ordinal,'due_on',due_on,'amount_cents',amount_cents::text,'cash_cents',cash::text,'credit_cents',credit::text,'discount_cents',discount::text,'loss_cents',loss::text,'open_cents',case when open_cents>=0 then open_cents::text end,'status',case when open_cents=0 then 'settled' when due_on<(statement_timestamp() at time zone 'America/Sao_Paulo')::date then 'overdue' else 'open' end)order by ordinal),'[]'),coalesce(sum(open_cents),0),coalesce(bool_and(open_cents>=0),true)
   into rows,scheduled,valid from checked;
  end if;
 end if;
 unallocated:=open_value-scheduled;if unallocated<0 then valid:=false;end if;requires:=status='active' and unallocated>0;
 rev:=md5(jsonb_build_object('tenant',_tenant,'receivable',_receivable,'snapshot_revision',s->>'revision','event',to_jsonb(e),'installments',rows,'history_count',history_count)::text);
 return jsonb_build_object('version',1,'tenant_id',_tenant,'actor_id',auth.uid(),'verified',valid and s->'requires_reconciliation'='false'::jsonb,'issue',case when not valid then 'finance_agreement_inconsistent' when s->'requires_reconciliation'<>'false'::jsonb then 'finance_receivable_unverified' when requires then 'finance_agreement_requires_reallocation' end,
  'receivable_id',_receivable,'agreement_id',agreement,'revision',rev,'status',status,'open_cents',case when valid then open_value::bigint::text end,'scheduled_open_cents',case when valid then scheduled::bigint::text end,'unallocated_open_cents',case when valid then unallocated::bigint::text end,'requires_reallocation',requires,'installments',rows,'history_count',history_count);
end$function$
;
